pr={}
for a,b in itertools.combinations_with_replacement(base,2):
    pr[a+'*'+b]=base[a]*base[b]
allf={**base,**pr}
keys=list(allf)
M=np.array([allf[q] for q in keys]).T
def score(s,extra):
    A=np.column_stack([np.sin(s*v)*np.sqrt(x)]+extra)
    c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    return np.mean((A@c-y)**2)/np.var(y),c
